#!/bin/bash
set -euo pipefail
mkdir -p "$(dirname /app/INTEGRATION.json)"
base64 -d > /app/INTEGRATION.json <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/server.ts)"
base64 -d > /app/src/server.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/session.ts)"
base64 -d > /app/src/session.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/transport.ts)"
base64 -d > /app/src/transport.ts <<'MB_ORACLE'

MB_ORACLE
